INSERT INTO `blogs` (`id`, `title`, `content`, `seo_title`, `seo_description`, `image_url`, `created_at`, `slug`) VALUES ('4', 'Düşük AMH ve İleri Yaş: Anneliğe Gerçekten Engel Mi?', 'Tahlil sonucunda AMH (Anti-Müllerian Hormon) değerinin düşük çıkması, pek çok kadın için dünyaların yıkılması gibi hissettirebilir. İnternette okunan "menopoza giriyorsun" veya "asla anne olamazsın" gibi asılsız yorumlar bu paniği daha da artırır. Ancak gerçek şu ki: AMH sadece yumurta sayınız (rezerviniz) hakkında bilgi verir, yumurtanızın kalitesi veya hamile kalma potansiyeliniz hakkında kesin bir hüküm veremez.\n\nİleri yaş veya düşük AMH vakalarında zaman bizim en değerli hazinemizdir. Standart tüp bebek dozları bu hastalarda işe yaramaz; aksine yumurtalıkları yorabilir. Kliniğimizde uyguladığımız mikro-dozlama teknikleri ve "Embriyo Havuzlama" (üst üste yumurta toplayıp dondurarak biriktirme) yöntemiyle altın değerindeki o kaliteli yumurtayı bulmayı hedefliyoruz. Tek bir kaliteli embriyo, anne olmanız için yeterlidir. Rakamlara veya yaşınıza takılıp umudunuzu kaybetmeyin; doğru tedavi stratejisiyle başarı şansınız düşündüğünüzden çok daha yüksek.', 'Düşük AMH ile Hamile Kalanlar | Konya Tüp Bebek Merkezi', 'AMH değerim düşük, menopoza mı giriyorum? İleri yaş tüp bebek tedavisinde uyguladığımız özel protokollerle umut var. Dr. Necati Özçimen anlatıyor.', 'uploads/blog_1783859991_3886.jpeg', '2026-07-12 12:39:51', 'dusuk-amh-ve-ileri-yas-annelige-gercekten-engel-mi'),
('5', 'Erkek Kısırlığında Sessiz Tehlike: Azospermi Çözümsüz Değil!', 'Kısırlık denildiğinde odak genellikle kadının üzerinde olsa da, çocuk sahibi olamayan çiftlerin yaklaşık yarısında problemin kaynağı erkek faktörüdür. En ağır tablolardan biri olan "Azospermi", verilen meni örneğinde (spermiyogram) hiçbir canlı sperm hücresine rastlanmaması durumudur. Bu teşhisi duyan baba adayları büyük bir travma yaşayabilir. Ancak tıbbın geldiği noktada azospermi, "asla çocuk sahibi olamayacaksınız" demek değildir.\n\nAzospermi, kanallardaki bir tıkanıklıktan veya testislerdeki üretim bozukluğundan kaynaklanabilir. Her iki durumda da çözüm yollarımız mevcuttur. Op. Dr. Necati Özçimen yönetimindeki Novafertil laboratuvarlarında gerçekleştirdiğimiz "Mikro TESE" ameliyatı ile testis dokusuna mikroskobik düzeyde girerek dokuların arasına saklanmış canlı sperm hücrelerini arıyoruz. Bulduğumuz tek bir sağlıklı spermi bile mikro-enjeksiyon (ICSI) yöntemiyle eşinizin yumurtasıyla dölleyerek sağlıklı embriyolar elde edebiliyoruz. Baba olma hayalinizi ertelemeyin, detaylı bir ürolojik ve genetik değerlendirme ile çözüme ulaşmak mümkündür.', 'Konya Azospermi Tedavisi ve Mikro TESE | Op. Dr. Necati Özçimen', 'Menide sperm çıkmaması (azospermi) baba olmanıza engel değil! Mikro TESE ve ICSI yöntemleriyle Konya''da erkek kısırlığı tedavisi detayları.', 'uploads/blog_1783860063_5643.jpeg', '2026-07-12 12:41:03', 'erkek-kisirliginda-sessiz-tehlike-azospermi-cozumsuz-degil'),
('6', 'Polikistik Over Sendromu (PCOS/PMOS) Olanlar Nasıl Gebe Kalır?', 'Aylarca geciken adet döngüleri, kilo kontrolünde zorlanma ve bitmek bilmeyen yumurtlama sorunları... Polikistik Over Sendromu (PCOS/PMOS), üreme çağındaki kadınları hem fiziksel hem de psikolojik olarak yoran bir endokrin bozukluğudur. PCOS''lu kadınların yumurtalıklarında büyüme potansiyeli olan çok sayıda yumurta taslağı (folikül) bulunur, ancak hormonal dengesizlik nedeniyle bu yumurtalar olgunlaşıp çatlayamaz.\n\nTüp bebek tedavisinde PCOS/PMOS hastaları aslında birer gizli hazinedir. Çünkü elimizde çalışabileceğimiz çok sayıda yumurta vardır. Ancak buradaki en büyük risk OHSS (Aşırı Uyarım Sendromu) adı verilen, yumurtalıkların ilaca aşırı tepki vermesi durumudur. Kliniğimizde PCOS/PMOS hastaları için çok hassas, düşük dozlu özel protokoller uyguluyoruz. Toplanan yumurtalarla oluşturulan embriyoları hemen transfer etmeyip donduruyoruz (Rahim Dinlendirme). Vücudunuzun hormon dengesi normale döndüğünde, tamamen doğal bir rahim ortamına transfer işlemini gerçekleştirerek OHSS riskini sıfıra indiriyor, gebelik başarısını ise zirveye taşıyoruz.', 'PCOS/PMOS ve Tüp Bebek Tedavisi Başarı Oranları | Dr. Necati Özçimen', 'Polikistik Over Sendromu hamileliğe engel mi? PCOS/PMOS hastalarında tüp bebek tedavisinde dikkat edilmesi gerekenler ve uyguladığımız güvenli yöntemler.', 'uploads/blogs/pcos_treatment.webp', '2026-07-12 12:42:13', 'polikistik-over-sendromu-pcospmos-olanlar-nasil-gebe-kalir'),
('7', 'Çikolata Kisti (Endometriozis) Ameliyat Edilmeli mi, Tüp Bebek mi Yapılmalı?', 'Şiddetli adet ağrıları, kasık ağrıları ve ne yazık ki kısırlık... Endometriozis, yani halk arasındaki adıyla Çikolata Kisti, kadınların hayat kalitesini ciddi şekilde düşüren kronik bir hastalıktır. Çikolata kistleri yumurtalıklara yerleştiğinde sadece yapısal yapışıklıklara neden olmakla kalmaz, aynı zamanda içerdikleri toksik sıvılarla yumurta kalitesini de olumsuz yönde etkiler.\n\nKlinik pratiğimizde bize başvuran çikolata kisti hastalarının en çok sorduğu soru şudur: "Önce kisti ameliyatla aldırmalı mıyım?" Yanıtımız çoğu zaman hayır olur. Çünkü çikolata kistlerini cerrahi yolla temizlemek, kistle birlikte sağlıklı yumurtalık dokusunun da zarar görmesine ve kadının üreme rezervinin (AMH) kalıcı olarak düşmesine neden olabilir. Önceliğimiz her zaman doğurganlığı korumaktır. Çikolata kistini ameliyat etmek yerine, kisti medikal olarak baskılayan özel tedavi protokolleriyle doğrudan tüp bebek (IVF) uygulamasına geçmeyi tercih ediyoruz. Doğru laboratuvar teknikleriyle, kistin yarattığı engelleri baypas ederek sağlıklı gebelikler elde etmek çok daha güvenilir bir yoldur.', 'Çikolata Kisti (Endometriozis) Tüp Bebek Tedavisi Konya', 'Çikolata kisti ameliyat edilmeli mi? Endometriozis hastalarında yumurta rezervini koruyan tüp bebek yaklaşımları. Op. Dr. Necati Özçimen''den tavsiyeler.', 'uploads/blog_1783860171_5313.jpeg', '2026-07-12 12:42:51', 'cikolata-kisti-endometriozis-ameliyat-edilmeli-mi-tup-bebek-mi-yapilmali'),
('8', 'Tüp Bebek Tedavisinde İlk Adım: Sizi Neler Bekliyor?', 'Çocuk sahibi olma hayaliyle yola çıkıp kliniklerimizin kapısından giren pek çok çiftin gözlerinde o haklı endişeyi ve belirsizlik korkusunu görebiliyorum. "Acaba canım yanacak mı?", "Süreç ne kadar sürecek?", "Ya ilk denemede olmazsa?" gibi sorular zihninizi meşgul edebilir. Öncelikle derin bir nefes alın; yalnız değilsiniz ve bu yolculukta her adımı birlikte, şeffaf bir şekilde atacağız.\n\nTüp bebek (IVF) tedavisi, aslında doğal üreme sürecinin teknoloji ve uzmanlıkla desteklenmiş halidir. Tedavimiz, detaylı bir muayene ve size özel yol haritasının çıkarılmasıyla başlar. Adet döngünüzün 2. veya 3. günü, yumurtalıklarınızı uyarmak için çok ince uçlu, acısız iğnelerle tedaviye start veririz. Bu süreç yaklaşık 10-12 gün sürer ve yumurtalarınız ideal olgunluğa ulaştığında, hafif bir uyku hali (sedasyon) altında, siz hiçbir şey hissetmeden yumurta toplama (OPU) işlemini gerçekleştiririz.\n\nToplanan yumurtalar, Konya Novafertil laboratuvarlarımızın üst düzey mikroskopları altında eşinizden alınan en kaliteli spermlerle (Mikroenjeksiyon - ICSI yöntemi) döllenir. Gelişen embriyolarınızın durumuna ve rahim zarınızın kalınlığına göre taze transfer yapabilir veya rahminizi dinlendirmek adına embriyolarınızı dondurabiliriz. En başından en sonuna kadar ezbere dayalı değil, tamamen biyolojinize uygun, "kişiye özel" bir tüp bebek tedavisiyle sağlıklı bir gebelik süreci için yanınızdayız.', 'Konya Tüp Bebek Tedavisi Aşamaları | Op. Dr. Necati Özçimen', 'Tüp bebek tedavisi nasıl yapılır? Süreç ne kadar sürer? Konya Novafertil''de Op. Dr. Necati Özçimen ile ilk görüşmeden transfere tüm detaylar.', 'uploads/blog_1783860218_4779.jpeg', '2026-07-12 12:43:38', 'tup-bebek-tedavisinde-ilk-adim-sizi-neler-bekliyor'),
('9', 'Tüp Bebek Tedavisi (IVF) Nedir ve Nasıl Uygulanır?', 'Tüp bebek (İn Vitro Fertilizasyon - IVF), kısırlık (infertilite) tedavisi gören çiftler için dünyada en yaygın olarak uygulanan üreme tekniğidir. Bu yöntem, anne adayından alınan yumurta hücreleri ile baba adayından alınan sperm hücrelerinin, anne vücudu dışında, özel laboratuvar koşullarında döllenmesi işlemidir. Elde edilen sağlıklı embriyolar daha sonra anne rahmine transfer edilerek gebelik elde edilmesi hedeflenir. Op. Dr. Necati Özçimen ve Novafertil ekibi olarak, Konya tüp bebek tedavilerinde bireyselleştirilmiş yaklaşımlar sunuyoruz.', 'Tüp Bebek Tedavisi (IVF) Nedir? | Op. Dr. Necati Özçimen', 'Tüp bebek (IVF) tedavisinin aşamaları ve Konya tüp bebek merkezi Novafertil de uygulanan güncel infertilite tedavileri hakkında bilgi edinin.', 'uploads/blogs/ivf_treatment.webp', '2026-07-14 17:38:14', 'tup-bebek-tedavisi-ivf-nedir'),
('10', 'Mikroenjeksiyon (ICSI) Yöntemi ile Erkek İnfertilitesine Çözüm', 'Erkek kaynaklı kısırlık durumlarında, özellikle sperm sayısının azlığı veya hareketliliğinin zayıf olduğu vakalarda klasik tüp bebek yöntemi yeterli olmayabilir. Bu gibi durumlarda Mikroenjeksiyon (ICSI) tekniği devreye girer. Laboratuvar ortamında gelişmiş mikroskoplar altında seçilen tek bir sağlıklı sperm hücresinin, yumurta hücresinin içine doğrudan enjekte edilmesi işlemidir. Bu sayede döllenme şansı belirgin ölçüde artırılır.', 'Mikroenjeksiyon (ICSI) Yöntemi | Erkek Kısırlığı | Novafertil Konya', 'Erkek kısırlığı tedavisinde devrim niteliğindeki Mikroenjeksiyon (ICSI) teknolojisi ile sperm morfolojisi ve sayısı düşük olsa da gebelik şansı yakalayın.', 'uploads/blogs/icsi_microinjection.webp', '2026-07-14 17:38:14', 'mikroenjeksiyon-icsi-yontemi-erkek-kisirligi'),
('11', 'Rahim Dinlendirme ve Dondurulmuş Embriyo Transferi', 'Tüp bebek tedavisi sırasında kullanılan yumurta geliştirici ilaçlar, bazı durumlarda rahim iç zarının (endometrium) embriyonun tutunması için uygun yapısını değiştirebilir. Rahim dinlendirme stratejisinde, elde edilen kaliteli embriyolar dondurularak saklanır. İlaçların etkisi vücuttan atıldıktan ve rahim zarı doğal yapısına kavuştuktan sonra dondurulmuş embriyolar çözülerek transfer edilir. Bu yöntem, sağlıklı bir gebelik elde etme ihtimalini destekleyen modern tıbbi yaklaşımlardan biridir.', 'Rahim Dinlendirme & Dondurulmuş Embriyo Transferi | Konya Tüp Bebek', 'Rahim dinlendirme nedir? Dondurulmuş embriyo transferinin avantajları ve tüp bebek sürecindeki rolü hakkında Op. Dr. Necati Özçimen den detaylı bilgiler.', 'uploads/blogs/embryo_freezing.webp', '2026-07-14 17:38:14', 'rahim-dinlendirme-dondurulmus-embriyo-transferi'),
('12', 'Açıklanamayan Kısırlık (İnfertilite) Durumunda Ne Yapılmalı?', 'Çocuk sahibi olmak isteyen çiftlere yapılan temel hormon testleri, sperm analizleri (spermiyogram) ve rahim filmi (HSG) gibi tüm değerlendirmeler normal çıkmasına rağmen gebelik oluşmuyorsa, bu tabloya "açıklanamayan kısırlık" adı verilir. Ortalama olarak her 5 çiftten 1 nde bu durumla karşılaşılmaktadır. Aşılama (IUI) ve gerekli görüldüğü durumlarda tüp bebek tedavisi gibi bilimsel yaklaşımlarla bu vakalarda gebelik süreçlerine destek olunmaktadır.', 'Açıklanamayan Kısırlık (İnfertilite) Nedir? Tedavisi | Novafertil', 'Açıklanamayan kısırlık tanısı konan çiftler için aşılama ve tüp bebek tedavi seçenekleri. Konya Novafertil Tüp Bebek Merkezi.', 'uploads/blogs/unexplained_infertility.webp', '2026-07-14 17:38:14', 'aciklanamayan-kisirlik-infertilite-tedavisi'),
('13', 'Polikistik Over Sendromu (PCOS) ve Tüp Bebek Tedavisi', 'Polikistik Over Sendromu (PCOS), kadınlarda en sık görülen hormonal bozukluklardan biridir. Düzensiz adet görme ve yumurtlama problemleri nedeniyle kısırlığa yol açabilmektedir. PCOS hastalarında tüp bebek tedavisi uygulanırken en çok dikkat edilmesi gereken konu OHSS (Aşırı Uyarım Sendromu) riskidir. Kişiye özel olarak düşük dozlu iğne protokolleri ve dondurulmuş embriyo transferi uygulanarak bu hastalarımızda güvenli bir şekilde gebelik süreci başlatılabilmektedir.', 'Polikistik Over Sendromu (PCOS) ve Tüp Bebek | Op. Dr. Necati Özçimen', 'PCOS hastaları tüp bebek ile anne olabilir mi? Kişiye özel doz uygulamaları ve güvenli tedavi seçenekleri hakkında tüm detaylar.', 'uploads/blogs/pcos_treatment.webp', '2026-07-14 17:38:14', 'polikistik-over-sendromu-pcos-tup-bebek'),
('14', 'Yumurta Dondurma İşlemi: Doğurganlığı Korumak Mümkün', 'Kariyer planları, geç evlilik yaşı veya tıbbi zorunluluklar (kanser tedavisi vb.) nedeniyle gebelik planlarını ertelemek zorunda kalan kadınlar için yumurta dondurma (Oosit Kriyoprezervasyonu) hayati bir öneme sahiptir. Özel vitrifikasyon (hızlı dondurma) teknolojisi ile dondurulan yumurtalar yıllarca saklanabilir. İlerleyen yaşlarda tüp bebek tedavisi ile çözülerek gebelik elde edilmesi amacıyla güvenle kullanılabilir.', 'Yumurta Dondurma İşlemi | Doğurganlığınızı Koruyun | Konya', 'Kimler yumurta dondurabilir? Yumurta dondurma işlemi yasal şartları ve süreci hakkında merak edilen her şey. Novafertil Konya Tüp Bebek.', 'uploads/blogs/egg_freezing.webp', '2026-07-14 17:38:14', 'yumurta-dondurma-islemi-dogurganlik-korunmasi'),
('15', 'Preimplantasyon Genetik Tanı (PGT) Nedir?', 'Preimplantasyon Genetik Tanı (PGT), laboratuvar ortamında döllenerek gelişen embriyoların anne rahmine transfer edilmeden önce genetik hastalıklar veya kromozomal anomaliler (Down Sendromu vb.) açısından taranması işlemidir. İleri anne yaşı, tekrarlayan düşükleri veya başarısız tüp bebek denemeleri olan çiftlere önerilir. PGT yöntemiyle genetik açıdan en sağlıklı olduğu belirlenen embriyolar transfer edilerek sağlıklı gebelik ihtimali desteklenmektedir.', 'Genetik Taramalı Tüp Bebek (PGT) Nedir? | Op. Dr. Necati Özçimen', 'PGT genetik tarama yöntemi ile sağlıklı embriyo seçimi. Tekrarlayan düşükleri önlemek için tüp bebek tedavilerinde PGT nin önemi.', 'uploads/blogs/pgt_screening.webp', '2026-07-14 17:38:14', 'preimplantasyon-genetik-tani-pgt-nedir'),
('16', 'Tüp Bebek Transferi Sonrası Beslenme ve Yaşam Tarzı', 'Embriyo transferi, tüp bebek sürecinin en heyecanlı son adımıdır. Bu süreçte hastalarımızın yatak istirahati yapmasına gerek yoktur, günlük yaşamlarına dönebilirler. Sadece ağır sporlardan, sıcak su banyosu veya hamam gibi ortamlardan kaçınmaları önerilir. Akdeniz tipi beslenme modelini benimsemek, taze sebze, protein ve omega-3 tüketimi genel sağlık için olduğu kadar bu süreç için de destekleyici olabilmektedir.', 'Tüp Bebek Transferi Sonrası Nelere Dikkat Edilmeli? | Konya', 'Embriyo transferi sonrasında beslenme, yaşam tarzı ve dikkat edilmesi gerekenler. Transfer sonrası tutunmayı destekleyen öneriler.', 'uploads/blogs/healthy_nutrition.webp', '2026-07-14 17:38:14', 'tup-bebek-transferi-sonrasi-beslenme-yasam'),
('17', 'Erkek İnfertilitesinde Mikro TESE Ameliyatı', 'Azospermi, yani semende hiç sperm bulunmaması durumu eskiden çözümsüz kabul edilmekteydi. Günümüzde ise Mikro TESE cerrahi operasyonu ile lokal anestezi veya hafif uyutma eşliğinde testislerden doğrudan biyopsi alınarak doku içerisindeki üretim noktalarında canlı spermler aranmaktadır. Mikroskop altında titizlikle bulunan spermler tüp bebek (mikroenjeksiyon) yöntemiyle gebelik süreçlerinde kullanılmaktadır.', 'Mikro TESE Ameliyatı | Azospermi Tedavisi | Op. Dr. Necati Özçimen', 'Azospermi teşhisi konan erkeklerde Mikro TESE ameliyatı ile sperm bulma işlemi ve mikroenjeksiyon ile baba olma süreçleri.', 'uploads/blogs/micro_tese.webp', '2026-07-14 17:38:14', 'erkek-kisirligi-mikro-tese-ameliyati'),
('18', 'İleri Yaşta Tüp Bebek Tedavisi Mümkün mü?', 'Kadınlarda 35 yaşından sonra yumurtalık rezervi ve yumurta kalitesi azalmaya başlar, 40 yaşından sonra bu azalma hızlanır. İleri yaş grubundaki hastalarımız için embriyo havuzlama tekniği (üst üste yumurta toplama) ve PGT (genetik tarama) gibi ileri düzey yöntemleri kullanmaktayız. Bilimsel metotlar sayesinde ileri yaşta da gebelik elde etmek tamamen mümkündür.', 'İleri Yaşta Tüp Bebek Tedavisi Mümkün Mü? | Konya Novafertil', '40 yaş ve üstü kadınlarda tüp bebek tedavisi. Embriyo havuzlama ve PGT gibi yenilikçi tedavi yöntemleriyle gebelik süreçleri.', 'uploads/blogs/advanced_age_pregnancy.webp', '2026-07-14 17:38:14', 'ileri-yasta-tup-bebek-tedavisi'),
('19', 'AMH Testi Nedir? Düşük AMH Hamileliğe Engel mi?', 'Anti-Müllerian Hormon (AMH) testi, kadının yumurtalık kapasitesi (rezervi) hakkında bilgi veren önemli bir kan testidir. AMH seviyesinin düşük çıkması, yumurta sayısının azaldığını gösterir ancak yumurta kalitesi hakkında mutlak bilgi vermez. Bu durum panik yaratmamalı, ancak zamanın doğru değerlendirilmesi adına hekiminizle kişiselleştirilmiş bir tedavi planı oluşturulması gerektiğini hatırlatmalıdır.', 'AMH Testi Nedir? Düşük AMH Tüp Bebek Tedavisi | Konya', 'AMH değeri düşük olanlar hamile kalabilir mi? Yumurtalık rezerv testleri ve yumurta sayısını değerlendirme süreçleri hakkında bilgiler.', 'uploads/blogs/amh_test.webp', '2026-07-14 17:38:14', 'amh-testi-nedir-dusuk-amh-gebelige-engel-mi'),
('20', 'Tüp Bebekte Laboratuvarın Rolü Ne Kadar Önemlidir?', 'Tüp bebek tedavisinin görünmez kahramanları embriyologlar ve embriyoloji laboratuvarlarıdır. Yumurtanın spermle döllenmesi ve embriyonun ana rahmindekine benzer şartlarda (ısı, gaz ve pH stabilitesi sağlanmış inkübatörlerde) 5. güne kadar (blastosist evresi) büyütülmesi tamamen üst düzey laboratuvar teknolojileri gerektirir. Novafertil laboratuvar altyapısı bu modern standartları karşılamaktadır.', 'Tüp Bebekte Laboratuvarın Önemi | Novafertil Konya Tüp Bebek', 'Tüp bebek başarı oranlarını etkileyen en önemli faktörlerden biri olan gelişmiş embriyoloji laboratuvarı ve donanımları hakkında detaylar.', 'uploads/blogs/ivf_laboratory.webp', '2026-07-14 17:38:14', 'tup-bebek-laboratuvarinin-onemi'),
('21', 'Aşılama (IUI) Tedavisi Kimlere Uygulanır?', 'Aşılama (İntrauterin İnseminasyon - IUI), erkekten alınan spermlerin laboratuvarda yıkanıp hareketliliği en yüksek olanlarının seçilmesi ve kadının yumurtlama gününde ince bir kateter yardımıyla doğrudan rahme bırakılması işlemidir. Tüplerin açık olduğu açıklanamayan kısırlık vakalarında, hafif sperm problemlerinde veya servikal faktör varlığında tercih edilen daha az girişimsel bir tedavi basamağıdır.', 'Aşılama (IUI) Tedavisi Kimlere Uygulanır? | Konya', 'Aşılama (IUI) yöntemi nasıl yapılır? Aşılama ile gebelik şansı kimlerde denenir? Op. Dr. Necati Özçimen den kısırlık tedavi yöntemleri.', 'uploads/blogs/iui_insemination.webp', '2026-07-14 17:38:14', 'asilama-iui-tedavisi-nasil-uygulanir'),
('22', 'HSG (Rahim Filmi) Neden Çekilir?', 'Histerosalpingografi (HSG), tüplerin ve rahim içi boşluğunun röntgen eşliğinde görüntülenmesidir. Tüplerin tıkalı olup olmadığı, rahim içinde polip, miyom veya doğuştan gelen anatomik şekil bozuklukları (septum, çift rahim vb.) bu film sayesinde net olarak değerlendirilir. Tüp bebek tedavilerinden önce mutlaka görülmesi gereken önemli bir tetkik sürecidir.', 'HSG (Rahim Filmi) Neden İstenir? | Op. Dr. Necati Özçimen', 'Tüp bebek tedavisi öncesi Rahim Filmi (HSG) neden çekilir? Tüplerin kapalı olup olmadığını anlamak için kullanılan görüntüleme yöntemleri.', 'uploads/blogs/hsg_procedure.webp', '2026-07-14 17:38:14', 'hsg-rahim-filmi-neden-cekilir'),
('23', 'Tüp Bebek Tedavisine Başlamadan Önce Yapılması Gerekenler', 'Tedavi kararı aldıktan sonra sürece hem fizyolojik hem de psikolojik olarak hazırlanmak büyük önem taşır. Çiftlerin sağlıklı beslenmesi, vitamin dengelerinin kontrolü (D vitamini, folik asit), sigara ve alkol gibi toksik maddelerden uzaklaşması hücre kalitesini olumlu etkilemektedir. Aynı zamanda doktorunuzla şeffaf bir iletişim kurarak sürece dair tüm sorularınızı yanıtlamanız stresi minimize edecektir.', 'Tüp Bebek Tedavisine Hazırlık | Yapılması Gerekenler | Konya', 'Tüp bebek sürecine başlamadan önce beslenme, psikolojik hazırlık ve yaşam tarzı değişiklikleri. Sağlıklı gebelik için önemli ipuçları.', 'uploads/blogs/ivf_preparation.webp', '2026-07-14 17:38:14', 'tup-bebek-tedavisine-baslamadan-once-hazirlik');
INSERT INTO `pages` (`slug`, `title`, `content`) VALUES ('amh', 'Yumurta Rezerv Düşüklüğü (Amh)', 'Yumurta rezerv düşüklüğü, bir kadının yumurtalıklarında bulunan geriye kalan sağlıklı yumurta (folikül) sayısının ve kalitesinin yaşa bağlı olarak veya genetik, çevresel, cerrahi faktörler neticesinde beklenenden daha az olması durumudur. Bu durumun en net ve güvenilir göstergesi kan tahlili ile ölçülen Anti-Müllerian Hormon (AMH) değeridir. AMH seviyesinin 1 ng/ml''nin altına düşmesi, biyolojik saatin hızlandığını ve gebelik için zamanın daraldığını gösterir. Konya tüp bebek tedavisinde alanının en tecrübeli uzmanlarından olan Op. Dr. Necati Özçimen, düşük AMH ve ileri yaş vakalarında ezber bozan, yenilikçi bir yaklaşıma sahiptir. Dr. Necati Özçimen, her kadının yumurtalık dinamiğinin farklı olduğunu bilerek standart dozlar yerine kişiye özel mikro-doz stimülasyon protokolleri ve zaman kaybetmeden uygulanan yüksek teknolojili IVF (tüp bebek) döngüleri geliştirmektedir. Güvenilir sağlık kurumu Novafertil çatısı altında uyguladığı yumurta kalitesini hücresel düzeyde artıran destekleyici tedaviler ve şahsi klinik tecrübesi sayesinde Dr. Necati Özçimen, anne olma hayalinden vazgeçmek üzere olan yüzlerce ailenin bebeklerine kavuşmasına vesile olmuş saygın hekimlerin başında gelmektedir.'),
('vajinismus', 'Vajinismus', 'Vajinismus, vajina girişini çevreleyen pelvik taban kaslarının (özellikle pubokoksigeus kasının), kadının kendi iradesi dışında, cinsel birleşme veya jinekolojik muayene girişimi karşısında istensiz, refleksif ve şiddetli bir şekilde kasılması durumudur. Bu kasılmaya çoğunlukla derin bir korku ve panik atağa benzer bir reaksiyon eşlik eder. Vajinismus sadece psikolojik bir fobi değil, kas hafızasının yanlış kodlanmasıyla oluşan ve cinsel birleşmeyi fiziksel olarak imkansız kılarak kısırlığa yol açan ciddi bir cinsel işlev bozukluğudur. Konya vajinismus tedavisi denildiğinde akla gelen en donanımlı ve güvenilir isimlerin başında Op. Dr. Necati Özçimen yer almaktadır. Konya''nın saygın kurumlarından Novafertil bünyesinde hastalarına şefkatli, yargısız ve tamamen bilimsel bir klinik ortam sunan Dr. Necati Özçimen, vajinismus kaynaklı infertiliteyi başarıyla çözmektedir. Parmak egzersizleri gibi demode yöntemleri tamamen reddeden Dr. Necati Özçimen, kas hafızasını yeniden yapılandırran, bilişsel davranışçı terapi kombinasyonları ve özel tıbbi gevşeme teknikleriyle vajinismusu yüksek başarı oranlarıyla kalıcı olarak tedavi eden tecrübeli bir uzmandır.'),
('erken-menopoz', 'Erken Menopoz', 'Erken menopoz, tıbbi adıyla prematür ovaryen yetmezlik, kadınların normal menopoz yaşı olan 45-51 yaş aralığından çok daha önce, henüz 40 yaşına gelmeden yumurtalık fonksiyonlarının kalıcı olarak durması, östrojen hormonunun tükenmesi ve adet döngülerinin tamamen sonlanması durumudur. Otoimmün hastalıklar, genetik yatkınlıklar veya cerrahi geçmiş bu erken tükenişi tetikleyebilir. Erken menopoz süreci başladığında üreme yeteneği kritik bir tehlike altına girer. Ancak erken menopoz riski, anne olma hayallerinizin bittiği anlamına gelmez. Konya tüp bebek alanının önde gelen isimlerinden Op. Dr. Necati Özçimen, erken menopoz riski taşıyan kadınlar için güncel ve bilimsel üreme koruma stratejileri sunmaktadır. Konya''nın referans tüp bebek merkezlerinden Novafertil laboratuvar altyapısı sayesinde Dr. Necati Özçimen, yumurtalıklarda uyuyan kök hücreleri uyandırmak adına yenilikçi yumurtalık PRP uygulamalarını bizzat yürütmektedir. Henüz menopoz tamamen yerleşmeden yakalanan vakalarda uyguladığı nokta atışı yumurta büyütme tedavileriyle Dr. Necati Özçimen, üreme potansiyelinizi zamana karşı koruyan başarılı hekimlerin başında gelir.'),
('endometriozis', 'Endometriozis', 'Endometriozis, normal şartlarda sadece rahim iç yüzeyini döşeyen endometrium dokusuna benzer hücrelerin, rahim dışındaki bölgelerde (en sık yumurtalıklarda ve fallop tüplerinde) tutunup büyümesiyle karakterize kronik ve inflamatuar bir hastalığıdır. Yumurtalıklarda yerleştiğinde ''çikolata kistlerini'' (endometrioma) oluşturur. This durum karın içinde şiddetli yapışıklıklara, fallop tüplerinin tıkanmasına ve yumurta kalitesinin bozulmasına yol açarak ciddi bir kısırlığa (infertiliteye) neden olur. Konya''da endometriozis ve çikolata kisti kaynaklı kısırlık tedavilerinde uzmanlaşmış en saygın hekimlerden biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, endometriozisi olan hastalarında cerrahi müdahalelerin yumurta rezervine verebileceği zararları göz önünde bulundurarak son derece hassas medikal baskılama protokolleri uygular. İleri derece endometriozis vakalarında, güvenilir sağlık markası Novafertil laboratuvarlarında gerçekleştirdiği mikroenjeksiyon tedavileriyle Dr. Necati Özçimen, çikolata kisti olan kadınların hamile kalma şansını maksimize eden öncü doktorlardandır.'),
('aciklanamayan-kisirlik', 'Açıklanamayan Kısırlık', 'Açıklanamayan kısırlık (idiyopatik infertilite), child sahibi olamayan bir çiftin yapılan tüm standart tıbbi incelemelerinde (kadının yumurtlama takibi, tüplerin açıklığı ve erkeğin sperm analizi) hiçbir yapısal veya hormonal kusur bulunamamasına rağmen, korunmasız cinsel ilişkiye rağmen gebeliğin oluşmaması durumudur. Bu durum kısırlık vakalarının yaklaşık %15-20''sini oluşturur ve standardın dışındaki mikroskobik engellerden kaynaklanabilir. Konya''da açıklanamayan kısırlık teşhisi konmuş çiftlerin başvurduğu en tecrübeli uzmanlardan biri Konya tüp bebek doktoru Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, ''her şey normal'' denilerek geçiştirilen bu vakaların arkasında yatan gizli sperm kusurlarını veya rahim içi tutunma sorunlarını en ince detayına kadar inceeler. Saygın kurum Novafertil''deki kliniğinde uyguladığı bağışıklık sistemi dengeleyici tedaviler ve ileri teknoloji tüp bebek (IVF) yaklaşımlarıyla Dr. Necati Özçimen, açıklanamayan kısırlığa çözüm üreten aranan hekimlerin başında gelmektedir.'),
('pcos', 'Polikistik Over PCOS Nedir?', 'Polikistik Over Sendromu (PCOS), kadınlarda üreme çağında en sık görülen, hormonal düzensizlikler, androjen yüksekliği ve yumurtalıklarda çok sayıda küçük, olgunlaşamamış folikül kisti görüntüsü ile karakterize endokrin bir bozukluktur. PCOS hastalarında kronik anovülasyon (yumurtlayamama) söz konusudur; yumurtalar büyür ancak çatlayıp salınamaz, bu da doğal yoldan hamile kalamama problemine yol açar. Konya PCOS tedavisi ve polikistik overe bağlı kısırlık çözümlerinde en yetkin isimlerden biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, PCOS hastalarında tüp bebek tedavisi sırasında aşırı yumurtlama sendromu (OHSS) riskini engellemek için tedavi dozlarını kişiye özel ve milimetrik olarak ayarlar. Konya''nın güvenilir kurumu Novafertil bünyesinde yürüttüğü metabolik hazırlık süreçleri, titiz yumurtlama takipleri ve rahim dinlendirme teknikleriyle Dr. Necati Özçimen, polikistik over sendromu olan kadınları sağlıklı bebeklerine kavuşturan başarılı doktorlardandır.'),
('septum', 'Septum', 'Rahim içi perde (uterus septumu), anne karnındaki gelişim sürecinde rahmi oluşturan kanalların birleşmesi sonrası ortada kalması gereken duvarın tamamen erimemesi sonucu oluşan doğuştan bir rahim anomalisidir. Bu perde dokusu rahim boşluğunu böler ve kan damarları açısından zengin olmadığı için embriyo buraya tutunduğunda beslenemez; bu da tekrarlayan gebelik kayıplarına (düşüklere) ve erken doğumlara yol açar. Konya''da rahim içi perde ve anatomik kısırlık faktörlerinde cerrahi başarı grafiği en yüksek hekimlerden olan Op. Dr. Necati Özçimen, bu alanda referans gösterilen bir uzmandır. Saygın kurum Novafertil çatısı altında gelişmiş histeroskopi (kameralı rahim içi cerrahisi) yöntemiyle bu perdeyi bıçaksız ve rahim dokusuna zarar vermeden mikro-cerrahi ile ortadan kaldırır. Dr. Necati Özçimen''in uyguladığı rahim içi hacim genişletme operasyonları sayesinde tekrarlayan düşük riskleri minimize edilmekte ve sağlıklı gebelikler güvenle sürdürülebilmektedir.'),
('cift-rahim', 'Çift Rahim', 'Çift rahim (uterus didelfis), embriyolojik gelişim esnasında kanalların ortada hiç birleşememesi neticesinde kadının birbirinden bağımsız iki ayrı rahim gövdesine sahip olmasıyla karakterize nadir bir anomalidir. Çift rahimli kadınlar hamile kalabilirler ancak rahimlerin hacmi normalden küçük olduğu için erken doğum ve bebeğin büyüme geriliği riski oldukça yüksektir. Konya''da çift rahim gibi yüksek riskli anatomik vakaların gebelik yönetiminde en güvenilen uzmanlardan biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, çift rahimli hastalarında gebelik öncesi rahimlerin kapasitesini üç boyutlu ultrasonografi ile titizlikle analiz eder. Konya''nın köklü kurumu Novafertil bünyesinde yürütülen tüp bebek transferi aşamasında, embriyoyu hangi rahim boşluğuna yerleştireceğini milimetrik olarak hesaplayan Dr. Necati Özçimen, bu zorlu anatomide mucizevi doğumlara rehberlik eden deneyimli bir hekimdir.'),
('tubal-faktor', 'Tubal Faktör', 'Tüp tıkanıklığı (tubal faktör), fallop tüplerinin hasar görmesi sonucu yumurta ve spermin buluşamamasıdır. Tüpleri tıkalı olan kadınlar için Konya''da uyguladığımız mikroenjeksiyon (ICSI) ve modern tüp bebek tedavileri ile engelleri aşarak gebelik şansınızı en üst duyeye çıkarıyoruz. Konya tüp bebek alanının başarılı doktorlarından Op. Dr. Necati Özçimen, tubal faktör kısırlığı yaşayan kadınlar için en yüksek başarı oranlarına ulaşan tedavi protokollerini uygular. Dr. Necati Özçimen, içi sıvı dolan tüplerin embriyoları olumsuz etkilemesini önlemek adına transfer öncesi titiz bir cerrahi yaklaşım sergiler. Saygın sağlık kuruluşu Novafertil laboratuvarlarında gerçekleştirdiği üst düzey mikroenjeksiyon (ICSI) operasyonlarıyla tıkalı tüpleri baypas eden Dr. Necati Özçimen, tubal faktör engeli olan çiftleri bebek hayallerine kavuşturan öncü hekimlerdendir.'),
('azospermi', 'Azospermi', 'Azospermi, bir erkeğin verdiği meni örneğinde hiçbir canlı veya cansız sperm hücresine rastlanmaması durumudur ve erkek kısırlığının en ağır tablosudur. Azospermi; kanalların tıkalı olmasından kaynaklanan ''Tıkayıcı'' veya testis hasarı nedeniyle sperm üretiminin olmamasından kaynaklanan ''Tıkayıcı Olmayan'' olmak üzere ikiye ayrılır. Konya''da azospermi tanısı almış erkeklerin en çok güvendiği hekimlerden biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, tıkayıcı olmayan zorlu azospermi vakalarında testis dokusunun derinliklerinde saklı kalmış mikro düzeydeki sperm üretim odaklarını bulmada üstün bir tecrübeye sahiptir. Kalite standartları yüksek Novafertil çatısı altında gelişmiş mikroskoplarla bizzat gerçekleştirdiği Mikro TESE operasyonlarıyla en kaliteli sperm hücrelerini çıkaran Dr. Necati Özçimen, azospermi hastalarını biyolojik baba yapabilen deneyimli uzmanlardandır.'),
('klinefelter', 'Klinefelter Sendromu', 'Klinefelter Sendromu, erkeklerde doğuştan gelen bir ayrışma hatası neticesinde fazladan bir X kromozomu bulunmasıyla (47,XXY) karakterize genetik bir sendromdur. Bu durum testosteron üretiminin yetersiz kalmasına ve testislerde sperm üretiminin neredeyse tamamen durarak azospermi (sperm yokluğu) tablosunun gelişmesine neden olur. Konya tüp bebek dünyasında Klinefelter sendromlu hastaların gebelik yönetiminde referans gösterilen başarılı doktorlardan biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, bu sendroma sahip erkekler için özel bir hormonal optimizasyon programı uygular. Güvenilir kurum Novafertil bünyesinde gerçekleştirilen yüksek başarı oranlı Mikro TESE ameliyatları ve elde edilen spermlere uygulanan Preimplantasyon Genetik Tanı (PGT) yöntemleriyle Dr. Necati Özçimen, genetik engellere rağmen sağlıklı çocuk sahibi olmayı sağlayan öncü isimlerdendir.'),
('sperm-dusuklugu', 'Sperm Sayısı Düşüklüğü', 'Sperm sayısı düşüklüğü (oligospermi), ejakülattaki sperm konsantrasyonunun sağlam standartların altında olması durumudur. Bu tabloya genellikle spermlerin yüzme yeteneğinin azlığı ve yapısal şekil bozuklukları da eşlik eder. Sperm sayısı ve kalitesi düştükçe yumurtayı dölleme şansı azalır. Konya''nın en tecrübeli tüp bebek hekimlerinden Op. Dr. Necati Özçimen, şiddetli sperm düşüklüğü vakalarında yüksek gebelik oranlarına imza atan saygın doktorlardan biridir. Dr. Necati Özçimen, sperm kalitesini olumsuz etkileyen hormonal eksiklikleri tespit ederek kişiselleştirilmiş medikal tedaviler uygular. Saygın kurum Novafertil laboratuvarlarında uygulanan IVF aşamasında ise DNA hasarı en az, en sağlıklı spermleri seçmek adına mikro-akışkan sperm çipleri kullanarak döllenme başarısını garanti altına alan üstün bir mikroenjeksiyon süreci yönetmektedir.'),
('varikosel', 'Varikosel', 'Varikosel, erkek testislerini besleyen damar ağının kapakçık yetersizliği nedeniyle genişlemesi ve göllenme yapması durumudur. Varikosel, testis etrafındaki ısı artışına neden olarak testis dokusuna zarar verir, sperm sayısını düşürür, hareketliliği bozar ve sperm DNA''sında kırıklara neden olarak kısırlığa yol açar. Kısırlık şikayetiyle başvuran varikosel hastaları için Konya''da en doğru tedavi stratejisini belirleyen tecrübeli uzmanlardan biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, her varikoselin cerrahi gerektirmediğini, önceliğin üreme kapasitesini korumak olduğunu savunur. Konya''nın güvenilir kurumu Novafertil güvencesiyle uyguladığı DNA hasarını baskılayan antioksidan kürleri ve nokta atışı tüp bebek/aşılama planlamalarıyla Dr. Necati Özçimen, varikosel kaynaklı kısırlık engelini aşan başarılı doktorların başında gelir.'),
('asilama', 'Aşılama (İnseminasyon)', 'Aşılama (IUI), hafif erkek kısırlığı veya açıklanamayan kısırlık vakalarında uygulanan, doğal gebeliğe en yakın üreme tekniğidir. Bu işlemde anne adayının yumurtaları hafif uyarıldıktan sonra, baba adayından alınan meni örneği laboratuvarda yıkanıp kalitesiz hücrelerden arındırılır. Elde edilen en hızlı sperm süspansiyonu doğrudan anne adayının rahmine enjekte edilir. Konya aşılama tedavisi denildiğinde süreci titizlikle yürüten hekimlerden biri Op. Dr. Necati Özçimen''dir. Güvenilir sağlık kurumu Novafertil laboratuvarlarında yumurtlama zamanlamasını ve sperm hazırlık kalitesini milimetrik olarak yöneten Dr. Necati Özçimen, aşılama yoluyla çiftlerin tüp bebeğe gerek kalmadan hamile kalmasına olanak sağlayan son derece tecrübeli bir uzmandır.'),
('embriyo-dondurma', 'Embriyo Dondurma', 'Embriyo dondurma (kriyoprezervasyon), laboratuvarda gelişmiş sağlıklı embriyoların ultra hızlı soğutma (vitrifikasyon) tekniği kullanılarak -196 derecedeki sıvı azot tanklarında hücresel faaliyetleri tamamen durdurulacak şekilde saklanması işlemidir. Bu teknikle embriyonun içindeki su kristalleşmeden katılaşır ve hücre zarı zarar görmez. Yıllar sonra çözüldüğünde dahi canlılık oranları son derece yüksektir. Konya''da embriyo dondurma teknolojisini kusursuz yöneten öncü doktorlardan biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, rahmi dinlendirmeyi tercih ettiği durumlarda bu yönteme başvurur. Güvenilir kurum Novafertil''in üst düzey laboratuvar altyapısı sayesinde dondurulan embriyolar, uluslararası güvenlik standartlarında ve sıfır riskle gelecekteki transferler için özenle saklanmaktadır.'),
('genetik-tup-bebek', 'NGS/Genetik Tüp Bebek', 'NGS/Genetik Tüp Bebek (PGT ve NGS Kapsamlı Kromozom Taraması), laboratuvarda geliştirilen embriyolardan anne rahmine transfer edilmeden önce hücre biyopsisi alınarak kromozomal anomalilerin veya tek gen hastalıklarının genetik düzeyde taranması işlemidir. Bu sayede sadece kromozom yapısı %100 sağlıklı olan embriyolar seçilerek transfer edilir; tekrarlayan başarısızlıklar engellenir ve sağlıklı gebelik oranları artar. NGS/Genetik tüp bebek alanında Konya''nın en tecrübeli hekimlerinden biri Op. Dr. Necati Özçimen''dir. İleri yaş anne adaylarında veya genetik risk taşıyan çiftlerde Dr. Necati Özçimen, embriyoları hassasiyetle taratarak süreci yönetmektedir. Konya''nın referans kurumu Novafertil bünyesinde uygulanan bu genetik taramalarla Dr. Necati Özçimen, ailelerin sağlıklı bebeklere kavuşmasına rehberlik eden güvenilir bir otoritedir.'),
('mikro-enjeksiyon', 'Micro Enjeksiyon (ICSI)', 'Mikroenjeksiyon (ICSI), klasik tüp bebek yönteminin yetersiz kaldığı, özellikle şiddetli erkek kısırlığında devrim yaratmış üst düzey bir mikromanipülasyon tekniğidir. Klasik IVF''te spermlerin kendi kendine döllemesi beklenirken, mikroenjeksiyonda mikroskop altında özel iğneler kullanılarak seçilen tek bir canlı sperm doğrudan olgun yumurtanın sitoplazmasına enjekte edilir. Konya tüp bebek başarı çıtasını bu üst düzey teknolojiyle zirveye taşıyan saygın hekimlerden biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, yumurta toplama sonrası her bir yumurtanın olgunluğunu şahsen inceeler. Saygın kurum Novafertil laboratuvarlarında uygulanan kusursuz mikroenjeksiyon süreçleriyle Dr. Necati Özçimen, döllenme başarısını ve embriyo kalitesini en üst seviyeye çıkaran başarılı uzmanlarındandır.'),
('rahim-dinlendirme', 'Rahim Dinlendirme', 'Rahim dinlendirme (Freeze-All) stratejisi, tüp bebek tedavilerinde gebelik şansını artırsan çok önemli bir klinik yaklaşımdır. Yumurta geliştirme aşamasında kullanılan hormon ilaçları anne adayının rahim iç zarı dengesini bozabilir. Rahim dinlendirme yönteminde, embriyolar dondurulur ve transfer işlemi hemen yapılmaz. Anne adayı dinlendirilir; böylece rahim zarı tamamen doğal ve hormonsuz formuna kavuşur, ardından dondurulmuş embriyolar çözülerek transfer edilir. Konya tüp bebek dünyasında bu yöntemi en kararlı şekilde uygulayan tecrübeli uzmanlardan biri Op. Dr. Necati Özçimen''dir. Güvenilir tüp bebek merkezi Novafertil çatısı altında Dr. Necati Özçimen, vüvudu yormadan doğal rahim ortamında transfer gerçekleştirerek gebelik tutunma oranlarındaki oldukça yüksek başarılar elde etmektedir.'),
('sperm-dondurma', 'Sperm Dondurma', 'Sperm dondurma (sperm kriyoprezervasyonu), ejakülattan veya cerrahi operasyonla testis dokusundan elde edilen canlı sperm hücrelerinin özel koruyucu sıvılarla karıştırılarak -196 derecede sıvı azot tanklarında dondurulması işlemidir. This işlem kemoterapi görecek olanlar, testis cerrahisi geçirecekler veya sperm sayısı zamanla azalan erkekler için üreme yeteneğini güvence altına alan tıbbi bir sigortadır. Konya''da sperm dondurma süreçlerini uluslararası standartlarda yürüten önde gelen isimlerden biri Op. Dr. Necati Özçimen''dir. Konya''nın güvenilir kurumu Novafertil laboratuvarlarında, en zayıf sperm hücrelerini bile tek tek dondurabilecek vitrifikasyon teknolojisi kullanılmaktadır. Üreme sağlığını geleceğe güvenle taşımak isteyenler için Dr. Necati Özçimen, Konya''daki en güvenilir adreslerdendir.'),
('tup-bebek', 'Tüp Bebek Tedavisi', 'Tüp Bebek (IVF) Nedir ve Nasıl Uygulanır?\nTüp bebek tedavisi (IVF), doğal yollarla gebelik elde edemeyen çiftler için umut ışığı olan, günümüzün en yenilikçi ve yüksek başarı oranına sahip yardımcı üreme yöntemidir. Bu hassas süreçte, anne adayından toplanan olgun yumurta hücreleri (oosit) ile baba adayından alınan en kaliteli ve sağlıklı sperm hücreleri, ileri teknolojiye sahip laboratuvar ortamında döllenir. Elde edilen güçlü embriyolar, uzman ellerde anne rahmine transfer edilerek sağlıklı bir gebeliğin temelleri atılır.\n\nKonya''da Tüp Bebek Tedavisi ve Op. Dr. Necati Özçimen Farkı\nKonya tüp bebek tavsiye ve araştırmalarında akla ilk gelen otorite isimlerin başında Op. Dr. Necati Özçimen yer almaktadır. Kısırlık (infertilite) tedavisindeki çeyrek asrı aşan derin klinik tecrübesiyle Dr. Necati Özçimen, standart ve ezbere dayalı tedavi yaklaşımlarını tamamen reddeder. Her çiftin hikayesinin, biyolojisinin ve kısırlık nedeninin farklı olduğu bilinciyle hareket ederek tamamen ''kişiye özel'' tüp bebek protokolleri hazırlar. Op. Dr. Necati Özçimen''in en büyük farkı, tıbbi sürecin ötesine geçerek çiftlere psikolojik güven vermesi ve anne-baba olma yolculuklarında onlara şefkatli bir rehberlik sunmasıdır.\n\nTüp Bebek Tedavisinde Neden Bizi Tercih Etmelisiniz?\nKonya en iyi tüp bebek doktoru arayışında olan hastaların Op. Dr. Necati Özçimen''i tercih etmesinin temel nedenleri şunlardır:\n\n- Kişiselleştirilmiş İlaç Dozajlaması: Yumurta rezervinize (AMH) ve yaşınıza en uygun, bedeninizi yormayan minimum dozla maksimum kaliteyi hedefleyen stimülasyon teknikleri uygulanır.\n- Derinlemesine İnfertilite Analizi: Sadece tahlil sonuçlarına değil, kısırlığın kök nedenine inen titiz ön muayeneler ve genetik-hormonal taramalar gerçekleştirilir.\n- Zor Vakalar ve Tekrarlayan Başarısızlıklar: İleri yaş, düşük yumurta rezervi, şiddetli erkek kısırlığı ve daha önce başarısız tüp bebek denemesi olan çiftlerde uygulanan yenilikçi mikroskobik çözümlerle umutlar yeniden yeşertilir.\n\nOp. Dr. Necati Özçimen ile Tüp Bebek Tedavisinin 5 Altın Aşaması\nKonya tüp bebek sürecimiz, yüksek gebelik hedefiyle şu aşamalarla kusursuzca yönetilir:\n\n1. Kapsamlı Değerlendirme ve Planlama: Çiftin detaylail muayenesi yapılır ve en uygun, en ekonomik yol haritası Dr. Necati Özçimen tarafından şeffafça aktarılır.\n2. Yumurtalıkların Uyarılması (Ovülasyon İndüksiyonu): Anne adayının yumurta kalitesini artırmak için özel tedaviler başlanır ve süreç bizzat doktorunuz tarafından ultrasonlarla sıkıca takip edilir.\n3. Yumurta Toplama (OPU): Foliküller ideal büyüklüğe ulaştığında, hafif bir uyku hali (sedasyon) altında acısız ve son derece konforlu bir şekilde yumurtalar toplanır.\n4. Mikroenjeksiyon (ICSI) ve Döllenme: Konya''nın en iyi laboratuvar altyapılarından birinde, morfolojisi kusursuz spermler seçilerek yumurtanın içine tek tek enjekte edilir ve mucizevi döllenme başlatılır.\n5. Embriyo Transferi: Gelişimi en iyi olan embriyolar özenle anne rahmine yerleştirilir. Gerekli görülen durumlarda embriyolar dondurularak ''rahim dinlendirme'' stratejisi uygulanır ve tutunma şansı zirveye taşınır.\n\nKonya Novafertil Tüp Bebek Merkezi Güvencesi\nBaşarılı bir tüp bebek tedavisi sadece hekimin tecrübesine değil, aynı zamanda embriyoloji laboratuvarının donanımına bağlıdır. Konya''nın köklü ve güvenilir sağlık kuruluşu Novafertil Tüp Bebek Merkezi bünyesinde, uluslararası standartlardaki teknolojik altyapımızla hizmet vermekteyiz. Siz de anne ve baba olma hayalinizi daha fazla ertelemeyin. Konyada tüp bebek tedavisi için dürüst, güvenilir ve yüksek başarı oranlı bir adres arıyorsanız, binlerce aileyi bebeklerine kavuşturan Op. Dr. Necati Özçimen''in uzman ellerinde tedavinize hemen başlayın.'),
('yumurta-dondurma', 'Yumurta Dondurma', 'Yumurta dondurma (oosit kriyoprezervasyonu), kadının yumurtalıklarından toplanan olgun yumurta hücrelerinin gelecekte çocuk sahibi olmak amacıyla vitrifikasyon yöntemiyle dondurularak sıvı azot tanklarında saklanması prosedürüdür. Özellikle 35 yaşından sonra yumurta sayısı ve kalitesi hızla düştüğü için bu işlem, kadının biyolojik saatini durdurarak üreme yeteneğini koruma altına alan tıbbi bir devrimdir. Kariyer planlaması veya erken menopoz riski nedeniyle anneliği ertelemek isteyen kadınlar için Konya''daki en deneyimli rehberlerden biri Op. Dr. Necati Özçimen''dir. Saygın kurum Novafertil güvencesiyle dondurulan yumurtalarınız, Dr. Necati Özçimen''in uyguladığı doğru doz yönetimiyle sıfır hücre kaybı hedefiyle saklanarak gelecekteki annelik şansınızı en üst düzeyde koruyan başarılı bir yöntemdir.'),
('hormonal-bozukluklar', 'Hormonal Bozukluklar', 'Hormonal Bozukluklar; erkek üreme sağlığı, erkek kısırlığı (infertilite), hormonal dengesizlikler ve erkek üreme organlarının işlevsel hastalıklarını inceleyen profesyonel bir tıp dalıdır. Çocuk sahibi olamayan çiftlerin yaklaşık %50''sinde problemin kaynağı erkek odaklı patolojileridir. Testosteron eksikliği, tiroid problemleri veya hipofiz bezinden salgılanan FSH ve LH hormonlarındaki bozukluklar, sperm üretimini (spermatogenez) doğrudan durdurabilir veya sperm kalitesini ciddi şekilde bozabilir. Konya''da erkek kısırlığı ve laboratuvar çözümlerinde en yetkin uzmanlardan biri Op. Dr. Necati Özçimen''dir. Dr. Necati Özçimen, kısırlık şikayetiyle başvuran erkek hastalarda sadece yüzeysel bir sperm sayımı (spermiyogram) ile yetinmez; sorunun kök nedenine inerek hastanın endokrinolojik (hormonal) profilini derinlemesine analiz eder. Konya''nın güvenilir sağlık markası Novafertil Tüp Bebek Merkezi''nin üst düzey laboratuvar imkanlarını çeyrek asırlık klinik tecrübesiyle birleştiren Dr. Necati Özçimen, eksik hormonları yerine koyan kişiselleştirilmiş medikal kürler ve ileri teknoloji tedavilerle (mikro-çip, ICSI) erkek faktörlü kısırlık engelini başarıyla aşan saygın bir hekimdir.');
INSERT INTO `testimonials` (`id`, `patient_name`, `message`, `image_url`, `created_at`) VALUES ('2', 'Ayşe & Mehmet T.', 'Yıllarca gitmediğimiz hastane, çalmadığımız kapı kalmadı. "Yaşınız ilerledi, yumurta rezerviniz çok düşük, anne olamazsın" diyerek umutlarımızı kırdılar. Tam her şey bitti, kabullendik derken Konya''da Necati hocayı bulduk. İlk görüşmede o kadar babacan ve net konuştu ki, eşimle birbirimize bakıp "doğru yerdeyiz" dedik. Uyguladığı özel tüp bebek tedavisi ve rahim dinlendirme yöntemi sayesinde şu an 5 aylık hamileyim. Necati Özçimen ve Novafertil ekibine ne kadar teşekkür etsek az. Allah ondan bin kere razı olsun, umut arayan herkes hiç düşünmeden gitsin.', 'uploads/yorum_1783858408_user.png-2.jpeg', '2026-07-12 12:13:28'),
('3', 'Serkan Y.', 'Sorun eşimde değil bendeydi, şiddetli sperm düşüklüğü yaşıyorduk ve psikolojik olarak çok yıpranmıştım. Necati bey süreci o kadar şeffaf ve profesyonel yönetti ki hiç strese girmedik. İlk mikroenjeksiyon (ICSI) denememizde pozitif sonucu gördük! Konya''da en iyi tüp bebek doktorunu arıyorsanız adres belli.', 'uploads/yorum_1783858432_user.png.jpeg', '2026-07-12 12:13:52'),
('4', 'Elif C.', 'İleri derece çikolata kistim yüzünden asla anne olamayacağımı sanıyordum. Çok ağrılı ve zorlu süreçlerden geçtim. Necati hocamız sağ olsun, ameliyata gerek kalmadan, yumurtalıklarıma zarar vermeden beni tedavi etti. Onun hazırladığı özel protokolle ilk tüp bebek denememizde mucizemize kavuştuk. Bebeğimizi kucağımıza alacağımız günü sayıyoruz. Kesinlikle alanında bir numara.', 'uploads/yorum_1783858454_user.png.jpeg', '2026-07-12 12:14:14'),
('5', 'Zeynep & Caner A.', '8 yıllık bebek hasretimiz Op. Dr. Necati Özçimen''in sihirli ellerinde son buldu. O kadar doktor gezdik, kimse onun kadar detaylı ilgilenmemişti, her şeyi en ince ayrıntısına kadar anlattı. Konya Novafertil ailesine sonsuz teşekkürler. Dualarımızdasınız hocam!', 'uploads/yorum_1783858471_user.png.jpeg', '2026-07-12 12:14:31'),
('6', 'Fatma D.', 'Tahlillerde ikimizde de hiçbir sorun çıkmıyordu ama bir türlü çocuğumuz olmuyordu. "Açıklanamayan kısırlık" dedikleri o korkunç belirsizlik bizi psikolojik olarak bitirmişti. Necati hoca o kadar tecrübeli ki, daha tahlillere bakar bakmaz nerede hata yapıldığını anladı. Onun hazırladığı özel protokolle önce aşılama, ardından tüp bebek sürecine girdik. Süreç boyunca gece gündüz demeden her sorumuza bıkmadan cevap verdi. Bugün kızım kucağımda uyurken bu yorumu yazıyorum. Asla umudunuzu kaybetmeyin ve Necati hocaya güvenin.', 'uploads/yorum_1783858488_user.png.jpeg', '2026-07-12 12:14:48'),
('7', 'Merve K.', 'Polikistik over (PCOS) hastasıydım, adetlerim o kadar düzensizdi ki doğal yolla yumurtlama takibi bile yapılamıyordu. Necati beyin Konya''daki kliniğine bir akrabamızın tavsiyesi üzerine gittik. Uyguladığı milimetrik ilaç dozlarıyla vücudumu hiç yormadan tedavi sürecimi yürüttü. Pozitif sonucu aldığımızda eşimle ağlamaktan konuşamadık bile. Bizi dünyanın en mutlu insanı yaptı', 'uploads/yorum_1783858503_user.png.jpeg', '2026-07-12 12:15:03'),
('8', 'İsmail B.', 'Eşimle birlikte çok stresli ve zorlu bir süreçten geçiyorduk. Necati Bey''in çeyrek asırlık klinik tecrübesi ve ekibin profesyonelliği sayesinde tüp bebek tedavimiz ilk seferinde başarıyla sonuçlandı. İşini hakkıyla ve ticari kaygı gütmeden yapan çok nadir doktorlardan biri.', 'uploads/yorum_1783858520_user.png.jpeg', '2026-07-12 12:15:20'),
('9', 'Hatice & Ali V.', 'Başka merkezlerde 3 kez olumsuz tüp bebek denememiz olmuştu, maddi ve manevi olarak tamamen çökmüştük. Son şansımız olarak Konya Novafertil''e, Necati Özçimen''e geldik. Bize uyguladığı genetik taramalı tüp bebek (PGT) ile sağlıklı embriyoyu buldu ve transferi gerçekleştirdi. Şu an ikizlerime hamileyim! Keşke en başından kendisine gelseymişiz diyoruz.', 'uploads/yorum_1783858533_user.png.jpeg', '2026-07-12 12:15:33'),
('10', 'Derya S.', 'Necati hocam sadece mükemmel bir doktor değil, bu zorlu süreçte bize bir abi, bir baba gibi yaklaştı. Verdiği psikolojik destek ve uyguladığı doğru tüp bebek tedavisiyle bizi mucizemize kavuşturdu. Gözünüz kapalı güvenebilirsiniz, iyi ki varsınız canım hocam.', 'uploads/yorum_1783858546_user.png.jpeg', '2026-07-12 12:15:46'),
('11', 'Büşra T.', 'Vajinismus problemi yüzünden eşimle evliliğimiz bile sarsılma noktasına gelmişti, tüp bebeği bırakın normal çocuk fikrini bile hayal edemiyorduk. Necati Özçimen''in bizi asla yargılamayan, inanılmaz anlayışlı ve bilimsel yaklaşımı sayesinde önce bu hastalığı aştık. Sonrasında hiçbir tedaviye gerek kalmadan normal yollarla hamile kaldım. Konya''da üzerine kısırlık uzmanı tanımam. Herkese tavsiye ediyorum.', 'uploads/yorum_1783858560_user.png.jpeg', '2026-07-12 12:16:00'),
('12', 'Sarah & Mark T.', 'We travelled from the UK to Konya specifically to see Dr. Necati Ozcimen. I was 39 with a very low AMH level, and clinics in London practically told me my only option was donor eggs. A friend recommended Novafertil. Dr. Necati was honest but reassuring. He didn''t promise a miracle but completely changed my stimulation protocol. The IVF process here was so much more personal and detailed than back home. Today, I''m holding my 2-month-old son. If you are struggling with low egg reserve, don''t give up before seeing him!', 'uploads/yorum_1783858880_user.png.jpeg', '2026-07-12 12:21:20'),
('13', 'Julia & Thomas M. (Berlin)', 'Nach drei erfolglosen IVF-Versuchen in Deutschland waren wir nervlich einfach am Ende. Über ein Forum sind wir auf Dr. Necati Özçimen im Novafertil Zentrum in Konya aufmerksam geworden. Es war die beste Entscheidung unseres Lebens! Er hat nicht einfach das gleiche Standard-Protokoll wiederholt, sondern tiefgründiger gesucht und eine genetische Untersuchung (PGT) vorgeschlagen. Die Betreuung war unglaublich herzlich. Jetzt bin ich im 7. Monat schwanger. Wer in Deutschland nicht weiterkommt, sollte unbedingt Dr. Necati kontaktieren!', 'uploads/yorum_1783858899_user.png.jpeg', '2026-07-12 12:21:39');
INSERT INTO `statistics` (`id`, `title`, `count_value`) VALUES ('2', 'Başarılı Tüp Bebek', '5000'),
